fn tansig_approx(mut x: f32) -> f32 {
    // the inverted comparisons also catch NaN
    if !(x < 8.0) {
        return 1.0;
    }
    if !(x > -8.0) {
        return -1.0;
    }
    let mut sign = 1.0f32;
    if x < 0.0 {
        x = -x;
        sign = -1.0;
    }
    let i = (0.5f32 + 25.0 * x).floor() as usize;
    x -= 0.04f32 * i as f32;
    let mut y = TANSIG_TABLE[i];
    let dy = 1.0 - y * y;
    y = y + x * dy * (1.0 - y * x);
    sign * y
}

fn sigmoid_approx(x: f32) -> f32 {
    (0.5 + 0.5 * tansig_approx((0.5 * x as f64) as f32) as f64) as f32
}

fn activate(act: Act, x: f32) -> f32 {
    match act {
        Act::Sigmoid => sigmoid_approx(x),
        Act::Tanh => tansig_approx(x),
        Act::Relu => {
            if x < 0.0 {
                0.0
            } else {
                x
            }
        }
    }
}

const WEIGHTS_SCALE: f32 = 1.0 / 256.0;

impl Dense {
    fn compute(&self, out: &mut [f32], inp: &[f32]) {
        let (n, m) = (self.n_out, self.n_in);
        for i in 0..n {
            let mut sum = self.bias[i];
            for j in 0..m {
                sum += self.w[j * n + i] * inp[j];
            }
            out[i] = WEIGHTS_SCALE * sum;
        }
        for o in out[..n].iter_mut() {
            *o = activate(self.act, *o);
        }
    }
}

impl Gru {
    fn compute(&self, state: &mut [f32], inp: &[f32]) {
        let (mut z, mut r, mut h) = ([0f32; 128], [0f32; 128], [0f32; 128]);
        let (n, m) = (self.n, self.n_in);
        let stride = 3 * n;
        for i in 0..n {
            // update gate
            let mut sum = self.bias[i];
            for j in 0..m {
                sum += self.w[j * stride + i] * inp[j];
            }
            for j in 0..n {
                sum += self.rw[j * stride + i] * state[j];
            }
            z[i] = sigmoid_approx(WEIGHTS_SCALE * sum);
        }
        for i in 0..n {
            // reset gate
            let mut sum = self.bias[n + i];
            for j in 0..m {
                sum += self.w[n + j * stride + i] * inp[j];
            }
            for j in 0..n {
                sum += self.rw[n + j * stride + i] * state[j];
            }
            r[i] = sigmoid_approx(WEIGHTS_SCALE * sum);
        }
        for i in 0..n {
            // output
            let mut sum = self.bias[2 * n + i];
            for j in 0..m {
                sum += self.w[2 * n + j * stride + i] * inp[j];
            }
            for j in 0..n {
                sum += self.rw[2 * n + j * stride + i] * state[j] * r[j];
            }
            sum = activate(self.act, WEIGHTS_SCALE * sum);
            h[i] = z[i] * state[i] + (1.0 - z[i]) * sum;
        }
        state[..n].copy_from_slice(&h[..n]);
    }
}

// ---------- FFT (kiss_fft as in Opus, float) ----------

#[derive(Clone, Copy, Default)]
struct Cpx {
    r: f32,
    i: f32,
}

#[inline]
fn cmul(a: Cpx, b: Cpx) -> Cpx {
    Cpx { r: a.r * b.r - a.i * b.i, i: a.r * b.i + a.i * b.r }
}

#[inline]
fn cadd(a: Cpx, b: Cpx) -> Cpx {
    Cpx { r: a.r + b.r, i: a.i + b.i }
}

#[inline]
fn csub(a: Cpx, b: Cpx) -> Cpx {
    Cpx { r: a.r - b.r, i: a.i - b.i }
}

struct KissFft {
    nfft: usize,
    scale: f32,
    factors: Vec<usize>,
    bitrev: Vec<usize>,
    tw: Vec<Cpx>,
}

impl KissFft {
    fn new(n: usize) -> Self {
        const PI: f64 = 3.14159265358979323846264338327;
        let tw = (0..n)
            .map(|i| {
                let phase = (-2.0 * PI / n as f64) * i as f64;
                Cpx { r: phase.cos() as f32, i: phase.sin() as f32 }
            })
            .collect();
        let factors = kf_factor(n).expect("kiss_fft: unsupported size");
        let mut bitrev = vec![0; n];
        kf_bitrev(0, &mut bitrev, 0, 1, 1, &factors);
        KissFft { nfft: n, scale: 1.0 / n as f32, factors, bitrev, tw }
    }

    fn bfly4(&self, f: &mut [Cpx], fstride: usize, m: usize, n: usize, mm: usize) {
        if m == 1 {
            for i in 0..n {
                let g = &mut f[4 * i..];
                let s0 = csub(g[0], g[2]);
                g[0] = cadd(g[0], g[2]);
                let mut s1 = cadd(g[1], g[3]);
                g[2] = csub(g[0], s1);
                g[0] = cadd(g[0], s1);
                s1 = csub(g[1], g[3]);
                g[1] = Cpx { r: s0.r + s1.i, i: s0.i - s1.r };
                g[3] = Cpx { r: s0.r - s1.i, i: s0.i + s1.r };
            }
            return;
        }
        let (m2, m3) = (2 * m, 3 * m);
        for i in 0..n {
            let g = &mut f[i * mm..];
            let (mut t1, mut t2, mut t3) = (0, 0, 0);
            for j in 0..m {
                let s0 = cmul(g[j + m], self.tw[t1]);
                let s1 = cmul(g[j + m2], self.tw[t2]);
                let s2 = cmul(g[j + m3], self.tw[t3]);
                let s5 = csub(g[j], s1);
                g[j] = cadd(g[j], s1);
                let s3 = cadd(s0, s2);
                let s4 = csub(s0, s2);
                g[j + m2] = csub(g[j], s3);
                t1 += fstride;
                t2 += fstride * 2;
                t3 += fstride * 3;
                g[j] = cadd(g[j], s3);
                g[j + m] = Cpx { r: s5.r + s4.i, i: s5.i - s4.r };
                g[j + m3] = Cpx { r: s5.r - s4.i, i: s5.i + s4.r };
            }
        }
    }

    fn bfly3(&self, f: &mut [Cpx], fstride: usize, m: usize, n: usize, mm: usize) {
        let m2 = 2 * m;
        let epi3 = self.tw[fstride * m];
        for i in 0..n {
            let g = &mut f[i * mm..];
            let (mut t1, mut t2) = (0, 0);
            for k in 0..m {
                let s1 = cmul(g[k + m], self.tw[t1]);
                let s2 = cmul(g[k + m2], self.tw[t2]);
                let s3 = cadd(s1, s2);
                let mut s0 = csub(s1, s2);
                t1 += fstride;
                t2 += fstride * 2;
                g[k + m] = Cpx { r: g[k].r - s3.r * 0.5, i: g[k].i - s3.i * 0.5 };
                s0.r *= epi3.i;
                s0.i *= epi3.i;
                g[k] = cadd(g[k], s3);
                g[k + m2] = Cpx { r: g[k + m].r + s0.i, i: g[k + m].i - s0.r };
                g[k + m] = Cpx { r: g[k + m].r - s0.i, i: g[k + m].i + s0.r };
            }
        }
    }

    fn bfly5(&self, f: &mut [Cpx], fstride: usize, m: usize, n: usize, mm: usize) {
        let ya = self.tw[fstride * m];
        let yb = self.tw[fstride * 2 * m];
        let tw = &self.tw;
        for i in 0..n {
            let g = &mut f[i * mm..];
            for u in 0..m {
                let s0 = g[u];
                let s1 = cmul(g[u + m], tw[u * fstride]);
                let s2 = cmul(g[u + 2 * m], tw[2 * u * fstride]);
                let s3 = cmul(g[u + 3 * m], tw[3 * u * fstride]);
                let s4 = cmul(g[u + 4 * m], tw[4 * u * fstride]);
                let s7 = cadd(s1, s4);
                let s10 = csub(s1, s4);
                let s8 = cadd(s2, s3);
                let s9 = csub(s2, s3);
                g[u].r = g[u].r + (s7.r + s8.r);
                g[u].i = g[u].i + (s7.i + s8.i);
                let s5 = Cpx { r: s0.r + (s7.r * ya.r + s8.r * yb.r), i: s0.i + (s7.i * ya.r + s8.i * yb.r) };
                let s6 = Cpx { r: s10.i * ya.i + s9.i * yb.i, i: -(s10.r * ya.i + s9.r * yb.i) };
                g[u + m] = csub(s5, s6);
                g[u + 4 * m] = cadd(s5, s6);
                let s11 = Cpx { r: s0.r + (s7.r * yb.r + s8.r * ya.r), i: s0.i + (s7.i * yb.r + s8.i * ya.r) };
                let s12 = Cpx { r: s9.i * ya.i - s10.i * yb.i, i: s10.r * yb.i - s9.r * ya.i };
                g[u + 2 * m] = cadd(s11, s12);
                g[u + 3 * m] = csub(s11, s12);
            }
        }
    }

    /// Forward transform scaled by 1/N (as opus_fft).
    fn fft(&self, inp: &[Cpx], out: &mut [Cpx]) {
        for i in 0..self.nfft {
            out[self.bitrev[i]] = Cpx { r: self.scale * inp[i].r, i: self.scale * inp[i].i };
        }
        let mut fstride = [0usize; 16];
        fstride[0] = 1;
        let mut l = 0;
        loop {
            let (p, m) = (self.factors[2 * l], self.factors[2 * l + 1]);
            fstride[l + 1] = fstride[l] * p;
            l += 1;
            if m == 1 {
                break;
            }
        }
        let mut m = self.factors[2 * l - 1];
        for i in (0..l).rev() {
            let m2 = if i != 0 { self.factors[2 * i - 1] } else { 1 };
            match self.factors[2 * i] {
                2 => kf_bfly2(out, m, fstride[i]),
                4 => self.bfly4(out, fstride[i], m, fstride[i], m2),
                3 => self.bfly3(out, fstride[i], m, fstride[i], m2),
                5 => self.bfly5(out, fstride[i], m, fstride[i], m2),
                _ => {}
            }
            m = m2;
        }
    }
}

fn kf_factor(mut n: usize) -> Option<Vec<usize>> {
    let mut fac = vec![0usize; 64];
    let (mut p, mut stages, nbak) = (4, 0, n);
    loop {
        while n % p != 0 {
            p = match p {
                4 => 2,
                2 => 3,
                _ => p + 2,
            };
            if p > 32000 || p * p > n {
                p = n;
            }
        }
        n /= p;
        if p > 5 {
            return None;
        }
        fac[2 * stages] = p;
        if p == 2 && stages > 1 {
            fac[2 * stages] = 4;
            fac[2] = 2;
        }
        stages += 1;
        if n <= 1 {
            break;
        }
    }
    n = nbak;
    for i in 0..stages / 2 {
        fac.swap(2 * i, 2 * (stages - i - 1));
    }
    for i in 0..stages {
        n /= fac[2 * i];
        fac[2 * i + 1] = n;
    }
    fac.truncate(2 * stages);
    Some(fac)
}

fn kf_bitrev(mut fout: usize, f: &mut [usize], mut off: usize, fstride: usize, in_stride: usize, factors: &[usize]) {
    let (p, m) = (factors[0], factors[1]);
    if m == 1 {
        for j in 0..p {
            f[off] = fout + j;
            off += fstride * in_stride;
        }
        return;
    }
    for _ in 0..p {
        kf_bitrev(fout, f, off, fstride * p, in_stride, &factors[2..]);
        off += fstride * in_stride;
        fout += m;
    }
}

fn kf_bfly2(f: &mut [Cpx], m: usize, n: usize) {
    if m == 1 {
        for i in 0..n {
            let g = &mut f[2 * i..];
            let t = g[1];
            g[1] = csub(g[0], t);
            g[0] = cadd(g[0], t);
        }
        return;
    }
    const TW: f32 = 0.7071067812;
    for i in 0..n {
        // m == 4
        let g = &mut f[8 * i..];
        let mut t = g[4];
        g[4] = csub(g[0], t);
        g[0] = cadd(g[0], t);
        t = Cpx { r: (g[5].r + g[5].i) * TW, i: (g[5].i - g[5].r) * TW };
        g[5] = csub(g[1], t);
        g[1] = cadd(g[1], t);
        t = Cpx { r: g[6].i, i: -g[6].r };
        g[6] = csub(g[2], t);
        g[2] = cadd(g[2], t);
        t = Cpx { r: (g[7].i - g[7].r) * TW, i: -(g[7].i + g[7].r) * TW };
        g[7] = csub(g[3], t);
        g[3] = cadd(g[3], t);
    }
}

// ---------- pitch search (pitch.c, celt_lpc.c) ----------

fn inner_prod(x: &[f32], y: &[f32], n: usize) -> f32 {
    let mut s = 0f32;
    for i in 0..n {
        s += x[i] * y[i];
    }
    s
}

fn pitch_xcorr(x: &[f32], y: &[f32], xcorr: &mut [f32], n: usize, max_pitch: usize) {
    for i in 0..max_pitch {
        xcorr[i] = inner_prod(x, &y[i..], n);
    }
}

fn celt_autocorr(x: &[f32], ac: &mut [f32], lag: usize, n: usize) {
    let fast_n = n - lag;
    pitch_xcorr(x, x, ac, fast_n, lag + 1);
    for k in 0..=lag {
        let mut d = 0f32;
        for i in k + fast_n..n {
            d += x[i] * x[i - k];
        }
        ac[k] += d;
    }
}

fn celt_lpc(lpc: &mut [f32], ac: &[f32], p: usize) {
    lpc[..p].fill(0.0);
    let mut errv = ac[0];
    if ac[0] == 0.0 {
        return;
    }
    for i in 0..p {
        let mut rr = 0f32;
        for j in 0..i {
            rr += lpc[j] * ac[i - j];
        }
        rr += ac[i + 1];
        let r = -rr / errv;
        lpc[i] = r;
        for j in 0..(i + 1) >> 1 {
            let (t1, t2) = (lpc[j], lpc[i - 1 - j]);
            lpc[j] = t1 + r * t2;
            lpc[i - 1 - j] = t2 + r * t1;
        }
        errv = errv - r * r * errv;
        if errv < 0.001 * ac[0] {
            break;
        }
    }
}

fn pitch_downsample(x: &[f32], xlp: &mut [f32], n: usize) {
    for i in 1..n >> 1 {
        xlp[i] = 0.5 * (0.5 * (x[2 * i - 1] + x[2 * i + 1]) + x[2 * i]);
    }
    xlp[0] = 0.5 * (0.5 * x[1] + x[0]);
    let mut ac = [0f32; 5];
    celt_autocorr(xlp, &mut ac, 4, n >> 1);
    ac[0] *= 1.0001;
    for i in 1..=4 {
        ac[i] -= ac[i] * (0.008f32 * i as f32) * (0.008f32 * i as f32);
    }
    let mut lpc = [0f32; 4];
    celt_lpc(&mut lpc, &ac, 4);
    let mut tmp = 1f32;
    for l in lpc.iter_mut() {
        tmp = 0.9 * tmp;
        *l = *l * tmp;
    }
    const C1: f32 = 0.8;
    let num = [lpc[0] + 0.8, lpc[1] + C1 * lpc[0], lpc[2] + C1 * lpc[1], lpc[3] + C1 * lpc[2], C1 * lpc[3]];
    let mut mem = [0f32; 5];
    for v in xlp[..n >> 1].iter_mut() {
        // celt_fir5 in place
        let mut sum = *v;
        sum = sum + num[0] * mem[0];
        sum = sum + num[1] * mem[1];
        sum = sum + num[2] * mem[2];
        sum = sum + num[3] * mem[3];
        sum = sum + num[4] * mem[4];
        mem = [*v, mem[0], mem[1], mem[2], mem[3]];
        *v = sum;
    }
}

fn find_best_pitch(xcorr: &[f32], y: &[f32], n: usize, max_pitch: usize) -> [i32; 2] {
    let mut syy = 1f32;
    let mut best_num = [-1f32, -1.0];
    let mut best_den = [0f32; 2];
    let mut best = [0i32, 1];
    for j in 0..n {
        syy = syy + y[j] * y[j];
    }
    for i in 0..max_pitch {
        if xcorr[i] > 0.0 {
            let mut x16 = xcorr[i];
            x16 *= 1e-12;
            let num = x16 * x16;
            if num * best_den[1] > best_num[1] * syy {
                if num * best_den[0] > best_num[0] * syy {
                    (best_num[1], best_den[1], best[1]) = (best_num[0], best_den[0], best[0]);
                    (best_num[0], best_den[0], best[0]) = (num, syy, i as i32);
                } else {
                    (best_num[1], best_den[1], best[1]) = (num, syy, i as i32);
                }
            }
        }
        syy += y[i + n] * y[i + n] - y[i] * y[i];
        if 1.0 > syy {
            syy = 1.0;
        }
    }
    best
}

struct PitchScratch {
    xlp4: [f32; (PITCH_FR >> 2) as usize],
    ylp4: [f32; ((PITCH_FR + PITCH_MAX) >> 2) as usize],
    xcorr: [f32; (PITCH_MAX >> 1) as usize],
    yy: [f32; (PITCH_MAX / 2 + 1) as usize],
}

fn pitch_search(sc: &mut PitchScratch, xlp: &[f32], y: &[f32], n: usize, max_pitch: usize) -> i32 {
    let lag = n + max_pitch;
    let xlp4 = &mut sc.xlp4[..n >> 2];
    let ylp4 = &mut sc.ylp4[..lag >> 2];
    let xcorr = &mut sc.xcorr[..max_pitch >> 1];
    for (j, v) in xlp4.iter_mut().enumerate() {
        *v = xlp[2 * j];
    }
    for (j, v) in ylp4.iter_mut().enumerate() {
        *v = y[2 * j];
    }
    pitch_xcorr(xlp4, ylp4, xcorr, n >> 2, max_pitch >> 2);
    let mut best = find_best_pitch(xcorr, ylp4, n >> 2, max_pitch >> 2);
    for i in 0..max_pitch >> 1 {
        xcorr[i] = 0.0;
        if (i as i32 - 2 * best[0]).abs() > 2 && (i as i32 - 2 * best[1]).abs() > 2 {
            continue;
        }
        let mut sum = inner_prod(xlp, &y[i..], n >> 1);
        if -1.0 > sum {
            sum = -1.0;
        }
        xcorr[i] = sum;
    }
    best = find_best_pitch(xcorr, y, n >> 1, max_pitch >> 1);
    let mut offset = 0;
    if best[0] > 0 && best[0] < (max_pitch as i32 >> 1) - 1 {
        let b0 = best[0] as usize;
        let (a, b, c) = (xcorr[b0 - 1], xcorr[b0], xcorr[b0 + 1]);
        if (c - a) > 0.7 * (b - a) {
            offset = 1;
        } else if (a - c) > 0.7 * (b - c) {
            offset = -1;
        }
    }
    2 * best[0] - offset
}

fn pitch_gain(xy: f32, xx: f32, yy: f32) -> f32 {
    (xy as f64 / ((1.0 + xx * yy) as f64).sqrt()) as f32
}

const SECOND_CHECK: [i32; 16] = [0, 0, 3, 2, 3, 2, 5, 2, 3, 2, 3, 2, 5, 2, 3, 2];

fn dual_inner_prod(x: &[f32], y1: &[f32], y2: &[f32], n: usize) -> (f32, f32) {
    let (mut a, mut b) = (0f32, 0f32);
    for i in 0..n {
        a = a + x[i] * y1[i];
        b = b + x[i] * y2[i];
    }
    (a, b)
}

/// max16/min16 as the MAX16/MIN16 macros of the original (a > b ? a : b).
#[inline]
fn max16(a: f32, b: f32) -> f32 {
    if a > b { a } else { b }
}

#[inline]
fn min16(a: f32, b: f32) -> f32 {
    if a < b { a } else { b }
}

/// x — the whole buffer; the original's "zero" point is x[maxperiod/2].
#[allow(clippy::too_many_arguments)]
fn remove_doubling(sc: &mut PitchScratch, x: &[f32], mut maxperiod: i32, mut minperiod: i32, mut n: i32, t0p: &mut i32, mut prev_period: i32, prev_gain: f32) -> f32 {
    let minperiod0 = minperiod;
    maxperiod /= 2;
    minperiod /= 2;
    *t0p /= 2;
    prev_period /= 2;
    n /= 2;
    let b = maxperiod as usize;
    let nu = n as usize;
    if *t0p >= maxperiod {
        *t0p = maxperiod - 1;
    }
    let t0 = *t0p;
    let mut t = t0;
    let yyl = &mut sc.yy[..maxperiod as usize + 1];
    let (xx, mut xy) = dual_inner_prod(&x[b..], &x[b..], &x[b - t0 as usize..], nu);
    yyl[0] = xx;
    let mut yy = xx;
    for i in 1..=maxperiod as usize {
        yy = yy + x[b - i] * x[b - i] - x[b + nu - i] * x[b + nu - i];
        yyl[i] = if 0.0 > yy { 0.0 } else { yy };
    }
    yy = yyl[t0 as usize];
    let (mut best_xy, mut best_yy) = (xy, yy);
    let g0 = pitch_gain(xy, xx, yy);
    let mut g = g0;
    for k in 2..=15i32 {
        let t1 = (2 * t0 + k) / (2 * k);
        if t1 < minperiod {
            break;
        }
        let t1b = if k == 2 {
            if t1 + t0 > maxperiod { t0 } else { t0 + t1 }
        } else {
            (2 * SECOND_CHECK[k as usize] * t0 + k) / (2 * k)
        };
        let (xy1, xy2) = dual_inner_prod(&x[b..], &x[b - t1 as usize..], &x[b - t1b as usize..], nu);
        xy = 0.5 * (xy1 + xy2);
        yy = 0.5 * (yyl[t1 as usize] + yyl[t1b as usize]);
        let g1 = pitch_gain(xy, xx, yy);
        let cont = if (t1 - prev_period).abs() <= 1 {
            prev_gain
        } else if (t1 - prev_period).abs() <= 2 && 5 * k * k < t0 {
            0.5 * prev_gain
        } else {
            0.0
        };
        let mut thresh = max16(0.3, 0.7 * g0 - cont);
        if t1 < 3 * minperiod {
            thresh = max16(0.4, 0.85 * g0 - cont);
        } else if t1 < 2 * minperiod {
            thresh = max16(0.5, 0.9 * g0 - cont);
        }
        if g1 > thresh {
            (best_xy, best_yy, t, g) = (xy, yy, t1, g1);
        }
    }
    if 0.0 > best_xy {
        best_xy = 0.0;
    }
    let mut pg = if best_yy <= best_xy { 1.0 } else { best_xy / (best_yy + 1.0) };
    let mut xc = [0f32; 3];
    for (k, v) in xc.iter_mut().enumerate() {
        *v = inner_prod(&x[b..], &x[(b as i32 - (t + k as i32 - 1)) as usize..], nu);
    }
    let mut offset = 0;
    if (xc[2] - xc[0]) > 0.7 * (xc[1] - xc[0]) {
        offset = 1;
    } else if (xc[0] - xc[2]) > 0.7 * (xc[1] - xc[2]) {
        offset = -1;
    }
    if pg > g {
        pg = g;
    }
    *t0p = 2 * t + offset;
    if *t0p < minperiod0 {
        *t0p = minperiod0;
    }
    pg
}

// ---------- shared tables ----------

struct Common {
    fft: KissFft,
    half_window: [f32; FRAME],
    dct_table: [f32; BANDS * BANDS],
}

static COMMON: LazyLock<Common> = LazyLock::new(|| {
    let mut half_window = [0f32; FRAME];
    for (i, w) in half_window.iter_mut().enumerate() {
        let s = (0.5 * std::f64::consts::PI * (i as f64 + 0.5) / FRAME as f64).sin();
        *w = (0.5 * std::f64::consts::PI * s * s).sin() as f32;
    }
    let mut dct_table = [0f32; BANDS * BANDS];
    for i in 0..BANDS {
        for j in 0..BANDS {
            let mut v = ((i as f64 + 0.5) * j as f64 * std::f64::consts::PI / BANDS as f64).cos() as f32;
            if j == 0 {
                v = (v as f64 * 0.5f64.sqrt()) as f32;
            }
            dct_table[i * BANDS + j] = v;
        }
    }
    Common { fft: KissFft::new(WINDOW), half_window, dct_table }
});

fn dct(out: &mut [f32], inp: &[f32]) {
    let c = &*COMMON;
    let scale = (2.0f64 / 22.0).sqrt();
    for i in 0..BANDS {
        let mut sum = 0f32;
        for j in 0..BANDS {
            sum += inp[j] * c.dct_table[j * BANDS + i];
        }
        out[i] = (sum as f64 * scale) as f32;
    }
}

fn band_energy(band_e: &mut [f32], x: &[Cpx]) {
    let mut sum = [0f32; BANDS];
    for i in 0..BANDS - 1 {
        let size = (EBAND[i + 1] - EBAND[i]) << 2;
        for j in 0..size {
            let frac = j as f32 / size as f32;
            let v = x[(EBAND[i] << 2) + j];
            let mut tmp = v.r * v.r;
            tmp += v.i * v.i;
            sum[i] += (1.0 - frac) * tmp;
            sum[i + 1] += frac * tmp;
        }
    }
    sum[0] *= 2.0;
    sum[BANDS - 1] *= 2.0;
    band_e[..BANDS].copy_from_slice(&sum);
}

fn band_corr(band_e: &mut [f32], x: &[Cpx], p: &[Cpx]) {
    let mut sum = [0f32; BANDS];
    for i in 0..BANDS - 1 {
        let size = (EBAND[i + 1] - EBAND[i]) << 2;
        for j in 0..size {
            let frac = j as f32 / size as f32;
            let k = (EBAND[i] << 2) + j;
            let mut tmp = x[k].r * p[k].r;
            tmp += x[k].i * p[k].i;
            sum[i] += (1.0 - frac) * tmp;
            sum[i + 1] += frac * tmp;
        }
    }
    sum[0] *= 2.0;
    sum[BANDS - 1] *= 2.0;
    band_e[..BANDS].copy_from_slice(&sum);
}

/// Fills 0..399 only; the rest (above 20 kHz) stays as it was — as in the original.
fn interp_band_gain(g: &mut [f32], band_e: &[f32]) {
    for i in 0..BANDS - 1 {
        let size = (EBAND[i + 1] - EBAND[i]) << 2;
        for j in 0..size {
            let frac = j as f32 / size as f32;
            g[(EBAND[i] << 2) + j] = (1.0 - frac) * band_e[i] + frac * band_e[i + 1];
        }
    }
}

// ---------- state and frame processing ----------

/// FFT work buffers.
struct Work {
    fin: [Cpx; WINDOW],
    fout: [Cpx; WINDOW],
}

fn apply_window(x: &mut [f32]) {
    let hw = &COMMON.half_window;
    for i in 0..FRAME {
        x[i] *= hw[i];
        x[WINDOW - 1 - i] *= hw[i];
    }
}

fn forward(w: &mut Work, out: &mut [Cpx], inp: &[f32]) {
    for i in 0..WINDOW {
        w.fin[i] = Cpx { r: inp[i], i: 0.0 };
    }
    COMMON.fft.fft(&w.fin, &mut w.fout);
    out[..FREQ].copy_from_slice(&w.fout[..FREQ]);
}

fn inverse(w: &mut Work, out: &mut [f32], inp: &[Cpx]) {
    let x = &mut w.fin;
    x[..FREQ].copy_from_slice(&inp[..FREQ]);
    for i in FREQ..WINDOW {
        x[i] = Cpx { r: x[WINDOW - i].r, i: -x[WINDOW - i].i };
    }
    COMMON.fft.fft(x, &mut w.fout);
    let y = &w.fout;
    out[0] = WINDOW as f32 * y[0].r;
    for i in 1..WINDOW {
        out[i] = WINDOW as f32 * y[WINDOW - i].r;
    }
}

fn pitch_filter(x: &mut [Cpx], p: &[Cpx], ex: &[f32], ep: &[f32], exp: &[f32], g: &[f32]) {
    let mut r = [0f32; BANDS];
    let mut rf = [0f32; FREQ];
    for i in 0..BANDS {
        if exp[i] > g[i] {
            r[i] = 1.0;
        } else {
            let num = exp[i] * exp[i] * (1.0 - g[i] * g[i]);
            let den = 0.001 + (g[i] * g[i] * (1.0 - exp[i] * exp[i])) as f64;
            r[i] = (num as f64 / den) as f32;
        }
        r[i] = (min16(1.0, max16(0.0, r[i])) as f64).sqrt() as f32;
        r[i] = (r[i] as f64 * (ex[i] as f64 / (1e-8 + ep[i] as f64)).sqrt()) as f32;
    }
    interp_band_gain(&mut rf, &r);
    for i in 0..FREQ {
        x[i].r += rf[i] * p[i].r;
        x[i].i += rf[i] * p[i].i;
    }
    let (mut new_e, mut norm) = ([0f32; BANDS], [0f32; BANDS]);
    let mut normf = [0f32; FREQ];
    band_energy(&mut new_e, x);
    for i in 0..BANDS {
        norm[i] = (ex[i] as f64 / (1e-8 + new_e[i] as f64)).sqrt() as f32;
    }
    interp_band_gain(&mut normf, &norm);
    for i in 0..FREQ {
        x[i].r *= normf[i];
        x[i].i *= normf[i];
    }
}

struct State {
    analysis_mem: [f32; FRAME],
    cepstral_mem: [[f32; BANDS]; CEPS_MEM],
    memid: usize,
    synthesis_mem: [f32; FRAME],
    pitch_buf: [f32; PITCH_BUF],
    last_gain: f32,
    last_period: i32,
    mem_hp: [f32; 2],
    lastg: [f32; BANDS],
    vad_state: [f32; 24],
    noise_state: [f32; 48],
    denoise_state: [f32; 96],

    // work buffers (no allocation on the audio thread)
    work: Work,
    x: [Cpx; FREQ],
    p: [Cpx; FREQ],
    win: [f32; WINDOW],
    plp: [f32; PITCH_BUF >> 1],
    ps: PitchScratch,
}

impl State {
    fn new() -> Box<Self> {
        LazyLock::force(&MODEL);
        LazyLock::force(&COMMON);
        Box::new(State {
            analysis_mem: [0.0; FRAME],
            cepstral_mem: [[0.0; BANDS]; CEPS_MEM],
            memid: 0,
            synthesis_mem: [0.0; FRAME],
            pitch_buf: [0.0; PITCH_BUF],
            last_gain: 0.0,
            last_period: 0,
            mem_hp: [0.0; 2],
            lastg: [0.0; BANDS],
            vad_state: [0.0; 24],
            noise_state: [0.0; 48],
            denoise_state: [0.0; 96],
            work: Work { fin: [Cpx::default(); WINDOW], fout: [Cpx::default(); WINDOW] },
            x: [Cpx::default(); FREQ],
            p: [Cpx::default(); FREQ],
            win: [0.0; WINDOW],
            plp: [0.0; PITCH_BUF >> 1],
            ps: PitchScratch {
                xlp4: [0.0; (PITCH_FR >> 2) as usize],
                ylp4: [0.0; ((PITCH_FR + PITCH_MAX) >> 2) as usize],
                xcorr: [0.0; (PITCH_MAX >> 1) as usize],
                yy: [0.0; (PITCH_MAX / 2 + 1) as usize],
            },
        })
    }

    /// Returns true when the frame is silent (then the network does not run).
    fn features(&mut self, ex: &mut [f32; BANDS], ep: &mut [f32; BANDS], exp: &mut [f32; BANDS], feat: &mut [f32; FEATURES], inp: &[f32]) -> bool {
        // frame analysis
        let x = &mut self.win;
        x[..FRAME].copy_from_slice(&self.analysis_mem);
        x[FRAME..].copy_from_slice(inp);
        self.analysis_mem.copy_from_slice(inp);
        apply_window(x);
        forward(&mut self.work, &mut self.x, x);
        band_energy(ex, &self.x);

        // pitch
        self.pitch_buf.copy_within(FRAME.., 0);
        self.pitch_buf[PITCH_BUF - FRAME..].copy_from_slice(inp);
        pitch_downsample(&self.pitch_buf, &mut self.plp, PITCH_BUF);
        let plp = &self.plp;
        let mut pitch_index = pitch_search(&mut self.ps, &plp[(PITCH_MAX >> 1) as usize..], plp, PITCH_FR as usize, (PITCH_MAX - 3 * PITCH_MIN) as usize);
        pitch_index = PITCH_MAX - pitch_index;
        let gain = remove_doubling(&mut self.ps, plp, PITCH_MAX, PITCH_MIN, PITCH_FR, &mut pitch_index, self.last_period, self.last_gain);
        (self.last_period, self.last_gain) = (pitch_index, gain);
        let p = &mut self.win;
        let base = PITCH_BUF - WINDOW - pitch_index as usize;
        p.copy_from_slice(&self.pitch_buf[base..base + WINDOW]);
        apply_window(p);
        forward(&mut self.work, &mut self.p, p);
        band_energy(ep, &self.p);
        band_corr(exp, &self.x, &self.p);
        for i in 0..BANDS {
            exp[i] = (exp[i] as f64 / (0.001 + (ex[i] * ep[i]) as f64).sqrt()) as f32;
        }
        let mut tmp = [0f32; BANDS];
        dct(&mut tmp, exp);
        feat[BANDS + 2 * DELTA..BANDS + 3 * DELTA].copy_from_slice(&tmp[..DELTA]);
        feat[BANDS + 2 * DELTA] = (feat[BANDS + 2 * DELTA] as f64 - 1.3) as f32;
        feat[BANDS + 2 * DELTA + 1] = (feat[BANDS + 2 * DELTA + 1] as f64 - 0.9) as f32;
        feat[BANDS + 3 * DELTA] = (0.01 * (pitch_index - 300) as f64) as f32;

        let mut ly = [0f32; BANDS];
        let (mut log_max, mut follow) = (-2f32, -2f32);
        let mut e = 0f32;
        for i in 0..BANDS {
            let l = (1e-2 + ex[i] as f64).log10() as f32 as f64;
            let mut a = follow as f64 - 1.5;
            if !(a > l) {
                a = l;
            }
            let mut c = (log_max - 7.0) as f64;
            if !(c > a) {
                c = a;
            }
            ly[i] = c as f32;
            log_max = max16(log_max, ly[i]);
            let mut f = follow as f64 - 1.5;
            if !(f > ly[i] as f64) {
                f = ly[i] as f64;
            }
            follow = f as f32;
            e += ex[i];
        }
        if (e as f64) < 0.04 {
            // silence — the network state is left alone
            feat.fill(0.0);
            return true;
        }
        dct(feat, &ly);
        feat[0] -= 12.0;
        feat[1] -= 4.0;
        let (i0, i1, i2) = (self.memid, (self.memid + CEPS_MEM - 1) % CEPS_MEM, (self.memid + CEPS_MEM - 2) % CEPS_MEM);
        self.cepstral_mem[i0].copy_from_slice(&feat[..BANDS]);
        self.memid += 1;
        let cm = &self.cepstral_mem;
        for i in 0..DELTA {
            let (c0, c1, c2) = (cm[i0][i], cm[i1][i], cm[i2][i]);
            feat[i] = c0 + c1 + c2;
            feat[BANDS + i] = c0 - c2;
            feat[BANDS + DELTA + i] = c0 - 2.0 * c1 + c2;
        }
        if self.memid == CEPS_MEM {
            self.memid = 0;
        }
        let mut spec_var = 0f32;
        for i in 0..CEPS_MEM {
            let mut mindist = 1e15f32;
            for j in 0..CEPS_MEM {
                let mut dist = 0f32;
                for k in 0..BANDS {
                    let t = cm[i][k] - cm[j][k];
                    dist += t * t;
                }
                if j != i {
                    mindist = min16(mindist, dist);
                }
            }
            spec_var += mindist;
        }
        feat[BANDS + 3 * DELTA + 1] = ((spec_var / CEPS_MEM as f32) as f64 - 2.1) as f32;
        false
    }

    fn rnn(&mut self, gains: &mut [f32], vad: &mut f32, inp: &[f32]) {
        let m = &*MODEL;
        let mut dense = [0f32; 24];
        let mut noise_in = [0f32; 24 + 24 + 42];
        let mut denoise_in = [0f32; 24 + 48 + 42];
        m.input_dense.compute(&mut dense, inp);
        m.vad_gru.compute(&mut self.vad_state, &dense);
        let mut v = [0f32; 1];
        m.vad_out.compute(&mut v, &self.vad_state);
        *vad = v[0];
        noise_in[..24].copy_from_slice(&dense);
        noise_in[24..48].copy_from_slice(&self.vad_state);
        noise_in[48..].copy_from_slice(&inp[..42]);
        m.noise_gru.compute(&mut self.noise_state, &noise_in);
        denoise_in[..24].copy_from_slice(&self.vad_state);
        denoise_in[24..72].copy_from_slice(&self.noise_state);
        denoise_in[72..].copy_from_slice(&inp[..42]);
        m.denoise_gru.compute(&mut self.denoise_state, &denoise_in);
        m.denoise_out.compute(gains, &self.denoise_state);
    }

    /// 480 samples in int16 scale → 480 cleaned ones (10 ms later), in place. Returns the voice
    /// probability 0..1.
    fn process_frame(&mut self, buf: &mut [f32]) -> f32 {
        let mut x = [0f32; FRAME];
        let a_hp = [-1.99599f32, 0.99600];
        let b_hp = [-2f32, 1.0];
        for i in 0..FRAME {
            // high-pass filter, intermediate values in double
            let xi = buf[i];
            let yi = buf[i] + self.mem_hp[0];
            self.mem_hp[0] = (self.mem_hp[1] as f64 + (b_hp[0] as f64 * xi as f64 - a_hp[0] as f64 * yi as f64)) as f32;
            self.mem_hp[1] = (b_hp[1] as f64 * xi as f64 - a_hp[1] as f64 * yi as f64) as f32;
            x[i] = yi;
        }
        let (mut ex, mut ep, mut exp, mut g) = ([0f32; BANDS], [0f32; BANDS], [0f32; BANDS], [0f32; BANDS]);
        let mut feat = [0f32; FEATURES];
        let mut vad = 0f32;
        let silence = self.features(&mut ex, &mut ep, &mut exp, &mut feat, &x);
        if !silence {
            self.rnn(&mut g, &mut vad, &feat);
            pitch_filter(&mut self.x, &self.p, &ex, &ep, &exp, &g);
            for i in 0..BANDS {
                const ALPHA: f32 = 0.6;
                g[i] = max16(g[i], ALPHA * self.lastg[i]);
                self.lastg[i] = g[i];
            }
            let mut gf = [0f32; FREQ];
            gf[0] = 1.0;
            interp_band_gain(&mut gf, &g);
            for i in 0..FREQ {
                self.x[i].r *= gf[i];
                self.x[i].i *= gf[i];
            }
        }
        // synthesis: inverse transform, window, overlap-add with the previous frame
        let w = &mut self.win;
        inverse(&mut self.work, w, &self.x);
        apply_window(w);
        for i in 0..FRAME {
            buf[i] = w[i] + self.synthesis_mem[i];
        }
        self.synthesis_mem.copy_from_slice(&w[FRAME..]);
        vad
    }
}

// ---------- wrapper for the microphone stream ----------

/// Rate conversion with an exact integer step (no drift) and cubic interpolation.
struct RateConv {
    from: u32,
    to: u32,
    h: [f32; 4],
    phase: u32,
}

impl RateConv {
    fn new(from: u32, to: u32) -> Self {
        RateConv { from, to, h: [0.0; 4], phase: 0 }
    }

    fn push(&mut self, x: f32, out: &mut Vec<f32>) {
        self.h = [self.h[1], self.h[2], self.h[3], x];
        while self.phase < self.to {
            out.push(catmull(self.h[0], self.h[1], self.h[2], self.h[3], self.phase as f32 / self.to as f32));
            self.phase += self.from;
        }
        self.phase -= self.to;
    }
}

/// RNNoise for any rate and channel count (channels are mixed to mono). Latency — 10 ms (+ a few
/// samples when the rate is not 48 kHz).
pub struct Denoiser {
    st: Box<State>,
    up: Option<RateConv>,
    down: Option<RateConv>,
    /// 48 kHz, waiting for a full frame
    acc: Vec<f32>,
    /// ready samples at the stream rate
    q: Vec<f32>,
    q_head: usize,
    frame: [f32; FRAME],
    pub vad: f32,
    /// how many times the queue ran empty (must not happen)
    pub under: usize,
}

impl Denoiser {
    pub fn new(fs: u32) -> Self {
        let mut pre = FRAME;
        let (mut up, mut down) = (None, None);
        if fs != 48000 {
            up = Some(RateConv::new(fs, 48000));
            down = Some(RateConv::new(48000, fs));
            pre = (FRAME * fs as usize).div_ceil(48000) + 8;
        }
        let mut q = Vec::with_capacity(pre + 4 * FRAME);
        q.resize(pre, 0.0);
        Denoiser { st: State::new(), up, down, acc: Vec::with_capacity(2 * FRAME), q, q_head: 0, frame: [0.0; FRAME], vad: 0.0, under: 0 }
    }

    fn run_frame(&mut self) {
        self.frame.copy_from_slice(&self.acc[..FRAME]);
        self.acc.drain(..FRAME);
        self.vad = self.st.process_frame(&mut self.frame);
        match &mut self.down {
            None => self.q.extend_from_slice(&self.frame),
            Some(d) => {
                for &v in &self.frame {
                    d.push(v, &mut self.q);
                }
            }
        }
    }

    /// Processes interleaved frames in place, values within ±1.
    pub fn process(&mut self, buf: &mut [f32], ch: usize) {
        let frames = buf.len() / ch;
        for k in 0..frames {
            let mut s = 0f32;
            for c in 0..ch {
                s += buf[k * ch + c];
            }
            s = s / ch as f32 * 32768.0;
            match &mut self.up {
                None => self.acc.push(s),
                Some(u) => u.push(s, &mut self.acc),
            }
            while self.acc.len() >= FRAME {
                self.run_frame();
            }
            let mut v = 0f32;
            if self.q_head < self.q.len() {
                v = self.q[self.q_head] / 32768.0;
                self.q_head += 1;
            } else {
                self.under += 1;
            }
            buf[k * ch..k * ch + ch].fill(v);
        }
        // compact the queue
        if self.q_head > 0 {
            self.q.drain(..self.q_head);
            self.q_head = 0;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::dsp::MicProc;

    /// The same integer signal as the C reference generator (a saw with a changing pitch + noise,
    /// silence, noise only, quiet voice with noise).
    fn test_signal(frames: usize) -> Vec<f32> {
        let mut out = vec![0f32; frames * FRAME];
        let mut seed = 12345u32;
        for (n, o) in out.iter_mut().enumerate() {
            seed = seed.wrapping_mul(1664525).wrapping_add(1013904223);
            let noise = ((seed >> 16) & 0x7fff) as i32 - 16384;
            let f = n / FRAME;
            let period = (180 + ((n / 4800) % 5) * 45) as i32;
            let ph = n as i32 % period;
            let saw = (ph * 12000) / period - 6000;
            let s = if f < 40 {
                saw + noise / 8
            } else if f < 45 {
                0
            } else if f < 80 {
                noise / 3
            } else {
                saw / 3 + noise / 4
            };
            *o = s as f32;
        }
        out
    }

    fn rms_of(b: &[f32]) -> f64 {
        (b.iter().map(|&v| v as f64 * v as f64).sum::<f64>() / b.len() as f64).sqrt()
    }

    /// Compares the port with the output of the original library (gcc -O2, x86-64).
    #[test]
    fn reference() {
        let raw = std::fs::read(concat!(env!("CARGO_MANIFEST_DIR"), "/../testdata/rnnoise_ref.bin")).unwrap();
        const PER: usize = 2 + 24;
        let frames = raw.len() / 4 / PER;
        let r: Vec<f32> = raw.chunks_exact(4).map(|b| f32::from_le_bytes([b[0], b[1], b[2], b[3]])).collect();
        let inp = test_signal(frames);
        let mut st = State::new();
        let (mut worst_vad, mut worst_rel) = (0f64, 0f64);
        let mut out = [0f32; FRAME];
        for f in 0..frames {
            out.copy_from_slice(&inp[f * FRAME..(f + 1) * FRAME]);
            let vad = st.process_frame(&mut out);
            let rf = &r[f * PER..(f + 1) * PER];
            let rms = rms_of(&out);
            worst_vad = worst_vad.max((vad - rf[0]).abs() as f64);
            let scale = (rf[1] as f64).max(1.0);
            worst_rel = worst_rel.max((rms - rf[1] as f64).abs() / scale);
            for i in 0..24 {
                worst_rel = worst_rel.max((out[i * 20] - rf[2 + i]).abs() as f64 / scale);
            }
        }
        println!("frames {frames}, max |Δvad| {worst_vad:.3e}, max relative sample error {worst_rel:.3e}");
        assert!(worst_vad <= 1e-3 && worst_rel <= 1e-3, "port differs from reference: vad {worst_vad:.3e}, samples {worst_rel:.3e}");
    }

    /// At 48 kHz the wrapper gives the same as frame processing, 480 samples later.
    #[test]
    fn denoiser_matches_frames() {
        let sig = test_signal(120);
        let mut st = State::new();
        let mut want = sig.clone();
        for f in 0..120 {
            st.process_frame(&mut want[f * FRAME..(f + 1) * FRAME]);
        }
        let mut d = Denoiser::new(48000);
        let mut buf = vec![0f32; 2 * sig.len()];
        for (i, &v) in sig.iter().enumerate() {
            buf[2 * i] = v / 32768.0;
            buf[2 * i + 1] = v / 32768.0;
        }
        let mut off = 0;
        while off < buf.len() {
            // uneven packets, as WASAPI gives
            let end = (off + 2 * 441).min(buf.len());
            d.process(&mut buf[off..end], 2);
            off = end;
        }
        for i in FRAME..sig.len() {
            let (g, w) = (buf[2 * i] * 32768.0, want[i - FRAME]);
            assert!((g - w).abs() <= 1e-3 && buf[2 * i + 1] == buf[2 * i], "sample {i}: got {g} want {w}");
        }
        assert_eq!(d.under, 0);
    }

    /// At other rates the noise after the voice is suppressed, the voice passes.
    #[test]
    fn denoiser_rates() {
        let sig = test_signal(120);
        for fs in [44100u32, 32000, 16000] {
            let mut d = Denoiser::new(fs);
            let mut buf: Vec<f32> = sig.iter().map(|&v| v / 32768.0).collect();
            let mut off = 0;
            while off < buf.len() {
                let end = (off + 300).min(buf.len());
                d.process(&mut buf[off..end], 1);
                off = end;
            }
            let delay = d.q.len(); // roughly
            let (voice_in, voice_out) = (rms_of(&sig[10 * FRAME..39 * FRAME]) / 32768.0, rms_of(&buf[10 * FRAME + delay..39 * FRAME + delay]));
            let (noise_in, noise_out) = (rms_of(&sig[60 * FRAME..79 * FRAME]) / 32768.0, rms_of(&buf[60 * FRAME + delay..79 * FRAME + delay]));
            println!("{fs} Hz: voice {voice_in:.4} → {voice_out:.4}, noise {noise_in:.4} → {noise_out:.4}");
            assert!(voice_out >= voice_in * 0.5 && noise_out <= noise_in * 0.2 && d.under == 0, "{fs} Hz: unexpected result (underflows {})", d.under);
        }
    }

    /// The queue neither drifts nor runs empty over a minute of sound.
    #[test]
    fn denoiser_latency() {
        for fs in [48000u32, 44100, 96000] {
            let mut d = Denoiser::new(fs);
            let pre = d.q.len();
            let mut buf = vec![0f32; 512];
            let mut max_q = 0;
            for _ in 0..fs as usize * 60 / 512 {
                d.process(&mut buf, 1);
                max_q = max_q.max(d.q.len());
            }
            assert!(d.under == 0 && max_q <= pre + 4, "{fs} Hz: underflows {}, max queue {max_q} (start {pre})", d.under);
        }
    }

    /// The denoiser in the microphone chain (stereo, switched on and off on the fly).
    #[test]
    fn mic_proc_denoise() {
        let mut m = MicProc::new(48000.0, 2);
        let sig = test_signal(80);
        let mut buf = vec![0f32; 2 * sig.len()];
        for (i, &v) in sig.iter().enumerate() {
            buf[2 * i] = v / 32768.0;
            buf[2 * i + 1] = v / 32768.0;
        }
        m.ctl.set_denoise(true);
        let mut off = 0;
        while off < buf.len() {
            if off == 960 * 300 {
                m.ctl.set_denoise(false);
            }
            if off == 960 * 320 {
                m.ctl.set_denoise(true);
            }
            let end = (off + 960).min(buf.len());
            m.process(&mut buf[off..end]);
            off = end;
        }
        let out = rms_of(&buf[2 * 72 * FRAME..2 * 79 * FRAME]);
        assert!(out <= 0.01, "noise after re-enable not suppressed: {out:.4}");
    }
}
